    ("js-postmessage", JS, "sink", "insecure-postmessage", "CWE-345", r"\.postMessage\([^)]*,\s*['\"]\*['\"]"),
    ("js-csrf-off", JS, "config", "csrf", "CWE-352", r"csrf\s*:\s*false|ignoreMethods|csrfProtection\s*=\s*false"),
    ("js-mass-assign", JS, "sink", "mass-assignment", "CWE-915",
     r"\.(create|update|updateOne|findByIdAndUpdate|findOneAndUpdate|build|insert|save)\(\s*(\{\s*\.\.\.)?\s*req\.body\s*[,)}]|new\s+\w+\(\s*req\.body\s*\)"),
    ("js-electron", JS, "config", "electron-misconfiguration", "CWE-1188",
     r"nodeIntegration\s*:\s*true|contextIsolation\s*:\s*false|webSecurity\s*:\s*false|sandbox\s*:\s*false|allowRunningInsecureContent\s*:\s*true|shell\.openExternal\(" + NONLIT),

